    def test_create_then_use_flow_miss_then_hit(self):
        payload = {'values': [1, 2, 3, 4, 5], 'cache_maxsize': 128, 'ttl': 60}
        s1status, d1 = wsgi_call('/api/run', 'POST', payload)
        self.assertTrue(s1status.startswith('200'), d1)
        r1 = d1['result']
        self.assertEqual(r1['count'], 5)
        self.assertAlmostEqual(r1['mean'], 3.0)
        self.assertAlmostEqual(r1['median'], 3.0)
        self.assertAlmostEqual(r1['min'], 1.0)
        self.assertAlmostEqual(r1['max'], 5.0)
        self.assertIn('stddev', r1)
        self.assertFalse(r1['cache_hit'])
        s2status, d2 = wsgi_call('/api/run', 'POST', payload)
        self.assertTrue(s2status.startswith('200'))
        r2 = d2['result']
        self.assertTrue(r2['cache_hit'])
        self.assertEqual(r2['mean'], r1['mean'])
        self.assertGreaterEqual(r2['hits'], r1['hits'] + 1)
        self.assertEqual(r2['cache_maxsize'], 128)
        self.assertEqual(r2['ttl'], 60.0)

    def test_two_nondefault_configs(self):
        p1 = {'values': [10, 20, 30], 'cache_maxsize': 5, 'ttl': 60}
        st, d = wsgi_call('/api/run', 'POST', p1)
        self.assertTrue(st.startswith('200'), d)
        self.assertFalse(d['result']['cache_hit'])
        self.assertEqual(d['result']['cache_maxsize'], 5)
        st2, d2 = wsgi_call('/api/run', 'POST', p1)
        self.assertTrue(d2['result']['cache_hit'])
        self.assertEqual(d2['result']['cache_size'], 1)
        p2 = {'values': [10, 20, 30], 'cache_maxsize': 7, 'ttl': 0}
        st3, d3 = wsgi_call('/api/run', 'POST', p2)
        self.assertTrue(st3.startswith('200'), d3)
        self.assertFalse(d3['result']['cache_hit'])
        self.assertEqual(d3['result']['cache_maxsize'], 7)
        self.assertEqual(d3['result']['ttl'], 0.0)
        st4, d4 = wsgi_call('/api/run', 'POST', p2)
        self.assertTrue(d4['result']['cache_hit'])

